(function(root){
'use strict';
const items=[{"id":"sexual-conduct","topic":"Scope and forum","question":"Is every bullying, rude remark or workplace dispute a POSH complaint?","answer":["Not every workplace grievance is sexual harassment under the POSH Act. Consider whether the reported conduct has a sexual element under Section 2(n), together with any connected circumstances under Section 3(2). A label such as bullying or unfair treatment does not decide the legal classification.","Other grievances can still be serious and may need a different employment, disciplinary or legal route. The free guidance helps identify questions to review; it does not determine jurisdiction, guilt or legal merits."],"basis":"Sections 2(n) and 3(2)","source":"act","popular":false,"keywords":"bullying harassment discrimination hostile environment"},{"id":"who-is-protected","topic":"Scope and forum","question":"Must an aggrieved woman be a permanent employee?","answer":["No. The Act’s definitions extend beyond permanent employees. An aggrieved woman may be employed or not employed at the workplace, and the employee definition covers several working arrangements.","The actual workplace connection and competent forum still need review. Do not rule out a concern solely because someone is an intern, contract worker, applicant or visitor."],"basis":"Sections 2(a), 2(f) and 2(o)","source":"act","popular":false,"keywords":""},{"id":"workplace-connection","topic":"Scope and forum","question":"Can conduct away from the office or online have a workplace connection?","answer":["The statutory concept of workplace is broader than an office desk. Work-related visits, activities and other circumstances can matter. Online conduct should be assessed in its factual work context rather than automatically included or excluded.","The location or communication channel alone does not establish a POSH case. Preserve lawful records and obtain a competent assessment of the connection."],"basis":"Sections 2(o), 2(n) and 3","source":"act","popular":false,"keywords":""},{"id":"ic-or-lc","topic":"Scope and forum","question":"What is the difference between the IC and the LC?","answer":["The Internal Committee (IC) is constituted at the workplace under Section 4. The Local Committee (LC) is constituted at district level. Section 6 addresses complaints from establishments with fewer than ten workers and complaints against the employer.","Forum selection must take account of the actual employer, establishment, Committee constitution and complaint. This website does not appoint, validate or choose a Committee for a live matter."],"basis":"Sections 4, 6 and 7","source":"act","popular":false,"keywords":"ICC LCC internal local ten employees jurisdiction employer","related":["appeal-ic-to-lc","who-constitutes-lc"]},{"id":"missing-or-unknown-ic","topic":"Scope and forum","question":"What if there is no IC, or I cannot find its details?","answer":["An IC that has not been constituted is different from an IC whose details you do not know. Ask for the constitution order, membership and contact details; seek appropriate employer or District Officer assistance promptly.","Protect the applicable complaint window while checking the forum. Do not wait indefinitely, assume that missing contact information proves non-constitution, or rely on this website to confirm LC competence in your particular circumstances."],"basis":"Sections 4, 6 and 9","source":"act","popular":false,"keywords":"missing absent unknown no committee escalation"},{"id":"different-employers","topic":"Scope and forum","question":"Does having different employers automatically prevent an inquiry?","answer":["Do not treat different employers as an automatic bar. The statutory wording and the relevant workplace facts need to be considered alongside current case law, the respondent’s applicable service rules and coordination between authorities.","The Section 11(1) safeguard refers to both parties being employees; it does not use the expression same employer. This does not mean that every Committee automatically has jurisdiction over every outside respondent."],"basis":"Section 11(1); forum and service-rule review","source":"judgment","popular":false,"keywords":"same employer different organisation external respondent"},{"id":"hr-versus-committee","topic":"Scope and forum","question":"Can HR or a manager replace the IC or decide the complaint alone?","answer":["An HR team or manager is not automatically the statutory Committee. The IC must be constituted in writing under Section 4 with the required membership. Employer support and implementation duties are distinct from the Committee’s inquiry role.","Ask for the constitution order and proper contact route. Sharing a concern with a manager is not proof that the competent Committee received it; preserve receipt records and check the applicable deadline."],"basis":"Sections 4, 9, 11 and 19","source":"act","popular":false,"keywords":"HR human resources manager employer internal committee"},{"id":"past-relationship","topic":"Scope and forum","question":"Does a past relationship or earlier friendly communication settle whether conduct was welcome?","answer":["No single label settles whether the reported conduct was unwelcome. Section 2(n) focuses on unwelcome conduct of a sexual nature; the particular conduct and context need assessment.","A previous relationship, friendly exchange or delay in reporting should not be used by this website to presume either consent or guilt. Present relevant facts accurately and leave findings to the competent process."],"basis":"Sections 2(n), 3 and 11","source":"act","popular":false,"keywords":"consent relationship friendly unwelcome welcome past"},{"id":"complaint-window","topic":"Complaint and timelines","question":"Is the complaint period three months or six months?","answer":["The normal Section 9 period is three months from the incident, or from the last incident in a series. A further extension of up to three months is possible where the Committee is satisfied about the circumstances preventing timely filing and records its reasons.","Six months is therefore not the automatic standard filing window. Do not assume an extension will be granted, or treat the site’s indicative date handling as a limitation decision."],"basis":"Section 9","source":"act","popular":false,"keywords":"limitation delay late extension 3 months 6 months"},{"id":"calendar-working-days","topic":"Complaint and timelines","question":"Are all POSH timelines working days?","answer":["No. The provisions use different units. Section 9 uses months; the Central Rule 7 complaint-copy and reply provisions use working days; the Act’s inquiry, report, action and appeal provisions state periods in days.","Check the exact provision, triggering event, applicable rules and calendar. Do not convert every deadline into working days or rely on a generic online calculator as an authoritative due date."],"basis":"Section 9; Central Rule 7; Sections 11, 13 and 18","source":"act","popular":false,"keywords":"calendar holidays counting dates deadlines"},{"id":"help-writing","topic":"Complaint and timelines","question":"Can someone get help if they cannot prepare a written complaint?","answer":["Section 9 provides for reasonable assistance in reducing a complaint to writing where the woman cannot do so. The permitted representative routes for incapacity, death or other specified circumstances have their own conditions under Section 9(2) and Central Rule 6.","The free Word draft is only a preparation aid. It neither replaces the statutory assistance duty nor gives every person an unrestricted right to file on someone else’s behalf."],"basis":"Section 9; Central Rule 6","source":"act","popular":false,"keywords":"oral complaint disability representative relative friend"},{"id":"seven-day-acceptance","topic":"Complaint and timelines","question":"Must the Committee accept or reject a complaint within seven days?","answer":["There is no general seven-day acceptance or rejection deadline in the provisions shown here. Under applicable Central Rule 7(2), the Committee must send the complaint copy to the respondent within seven working days of receipt.","Do not use a preliminary review to assume that applicable service obligations have stopped. Receipt, service and jurisdiction questions need accurate records and review under the applicable framework."],"basis":"Central Rule 7(2)","source":"rules","popular":true,"keywords":"7 days acceptance rejection preliminary review notice"},{"id":"submission-receipt","topic":"Complaint and timelines","question":"Are submission, receipt and acknowledgement the same thing?","answer":["No. Sending a complaint does not independently prove when the competent authority received it or what was acknowledged. Keep your submission record and seek a dated acknowledgement or receipt.","This website cannot establish those events. The date you select in the guidance remains your stated information; a generated document is not evidence that an IC, LC or employer has received or accepted it."],"basis":"Section 9; product filing boundary","source":"act","popular":false,"keywords":"filed email acknowledgment receipt service"},{"id":"respondent-reply","topic":"Complaint and timelines","question":"When does the respondent’s reply period start?","answer":["Under applicable Central Rule 7(3), the reply is due within ten working days after receipt of the prescribed complaint documents. The complaint-copy service period is a separate seven-working-day requirement.","Confirm actual service, materials and applicable rules; do not calculate from an unrelated email or assume the same procedural scheme applies in every workplace."],"basis":"Central Rule 7(1)–(3)","source":"rules","popular":false,"keywords":"10 days notice served documents particulars"},{"id":"anonymous-formal-complaint","topic":"Complaint and timelines","question":"Is an anonymous community post the same as a formal POSH complaint?","answer":["No. Posting here does not submit anything to an IC, LC, employer, police or government portal. Community aliases protect public presentation; they do not create a statutory complaint.","Section 9 requires a written complaint through the competent route, with assistance or a permitted representative where applicable. Seek confidential procedural guidance rather than relying on an anonymous post to preserve a filing deadline."],"basis":"Section 9; community filing boundary","source":"act","popular":false,"keywords":"anonymous pseudonymous formal filing deadline community"},{"id":"six-complaint-copies","topic":"Complaint and timelines","question":"Do I need six copies of the complaint, and under which rule?","answer":["Applicable Central Rule 7(1), subject to Section 11, calls for six copies of the complaint with supporting documents and witness names and addresses at filing. The complaint window itself comes from Section 9.","Confirm the governing procedure and secure submission arrangements with the competent Committee, including any officially accepted electronic route. Do not upload these records to this website or assume a local Word download meets the filing requirement."],"basis":"Central Rule 7(1), subject to Section 11; Section 9","source":"rules","popular":false,"keywords":"six 6 copies filing complaint documents witnesses"},{"id":"conciliation-voluntary","topic":"Conciliation and confidentiality","question":"Is conciliation compulsory before an inquiry?","answer":["No. Section 10 contemplates conciliation at the aggrieved woman’s request before the inquiry begins. It should not be treated as a mandatory compromise step or a reason to pressure either party.","The website’s optional request draft does not prove that a request is voluntary, that settlement terms are lawful, or that the competent Committee has recorded a settlement."],"basis":"Section 10","source":"act","popular":false,"keywords":"mediation settlement voluntary pressure"},{"id":"money-settlement","topic":"Conciliation and confidentiality","question":"Can a monetary settlement be the basis of Section 10 conciliation?","answer":["No. Section 10 expressly excludes monetary settlement as the basis of conciliation. This is distinct from the Act’s separate provisions concerning recommendations and compensation following an inquiry.","Do not use a payment promise to bypass statutory procedure or treat this FAQ as approval of proposed settlement terms."],"basis":"Sections 10, 13 and 15","source":"act","popular":false,"keywords":"money compensation cash settlement","related":["conciliation-voluntary","compensation-versus-conciliation","settlement-breach"]},{"id":"settlement-breach","topic":"Conciliation and confidentiality","question":"What if the respondent does not comply with a recorded settlement?","answer":["The Section 11(1) proviso addresses the situation where the aggrieved woman informs the Committee that a term or condition of the Section 10 settlement has not been complied with. The statutory route includes proceeding with inquiry or, as applicable, forwarding the complaint to police.","The response is not decided by this website, and a breach should not be treated as automatically establishing every underlying allegation."],"basis":"Section 11(1), first proviso","source":"act","popular":false,"keywords":"","related":["recorded-settlement","when-police-referral","conciliation-terms"]},{"id":"nda-required","topic":"Conciliation and confidentiality","question":"Must I sign an NDA before I can file a POSH complaint?","answer":["The POSH complaint provisions do not prescribe signing an NDA as a statutory filing condition. An institution may use a role-appropriate confidentiality undertaking, but it must be distinguished from the confidentiality duty imposed by law.","Any proposed undertaking should be reviewed so it preserves lawful reporting, fair-process disclosure and statutory remedies. The public demo does not generate an NDA or determine whether a particular contract is enforceable."],"basis":"Sections 9 and 16; institutional safeguard","source":"act","popular":true,"keywords":"NDA non disclosure confidentiality undertaking gag signature"},{"id":"confidentiality-without-nda","topic":"Conciliation and confidentiality","question":"Does confidentiality apply if nobody has signed an NDA?","answer":["Yes. Section 16 addresses public disclosure of complaint contents, identities and specified information about conciliation, inquiry, recommendations and action. The statutory duty does not arise only when an institutional form is signed.","Confidentiality must be applied alongside the parties’ procedural rights and lawful disclosures. A public community post is not a confidential channel for sharing case details."],"basis":"Sections 16 and 17; Sections 11 and 13","source":"act","popular":false,"keywords":"privacy public media witness identities disclosure"},{"id":"public-case-stories","topic":"Conciliation and confidentiality","question":"Can I post a case story if I remove the names?","answer":["Removing names alone may leave people identifiable through job titles, dates, screenshots or a unique incident. Section 16 restricts public disclosure of specified complaint and inquiry information.","Its proviso permits information about justice secured without identifying particulars of the aggrieved woman or witnesses. That is not general permission to publish case files. Use general questions in this community and obtain advice before disclosing material elsewhere."],"basis":"Section 16 and its proviso","source":"act","popular":false,"keywords":"social media linkedin whatsapp publicity redaction names confidentiality"},{"id":"conciliation-terms","topic":"Conciliation and confidentiality","question":"What should conciliation terms cover, and can the employer force a settlement?","answer":["Section 10 conciliation is at the aggrieved woman’s request before inquiry, and monetary settlement cannot be its basis. A manager or Committee must not turn it into compulsory compromise, an NDA-signing condition or a way to buy withdrawal of the complaint.","Terms need lawful, voluntary and workable content with clear implementation responsibilities. Non-monetary conduct or communication arrangements may need review, but this FAQ does not approve any particular settlement or draft binding terms. Avoid terms purporting to remove statutory reporting rights or mandatory duties. The Committee must record the settlement and follow the statutory forwarding and copy requirements."],"basis":"Section 10(1)–(3); lawful reporting and remedies","source":"act","popular":false,"keywords":"conciliation settlement terms voluntary forced employer NDA compromise money"},{"id":"recorded-settlement","topic":"Conciliation and confidentiality","question":"Who receives the conciliation settlement, and does an inquiry continue after it?","answer":["Under Section 10(2)–(3), the Committee records the settlement, forwards it to the employer or District Officer for the specified action, and gives copies to the aggrieved woman and respondent. An informal private conversation is not proof that this statutory process occurred.","Section 10(4) states no further inquiry after a settlement arrived at under Section 10(1). Distinguish that from Section 11(1)’s response when the woman informs the Committee of the respondent’s non-compliance with recorded terms: inquiry or, as applicable, police forwarding. Breach does not automatically prove every original allegation."],"basis":"Sections 10(2)–(4) and 11(1), first proviso","source":"act","popular":false,"keywords":"conciliation settlement record copies breach noncompliance resume inquiry"},{"id":"compensation-versus-conciliation","topic":"Conciliation and confidentiality","question":"If monetary conciliation is barred, can compensation ever be recommended?","answer":["Yes, these are different statutory routes. Section 10 bars monetary settlement as the basis of conciliation. Following inquiry, Section 13(3)(ii), read with Section 15, addresses recommendations for payment of compensation where the statutory conditions are met.","Do not turn a compensation provision into a pre-inquiry cash settlement, a fixed tariff or a website-calculated entitlement. The competent process must assess the relevant factors and lawful recommendation; this FAQ does not calculate damages or determine liability."],"basis":"Sections 10, 13(3)(ii) and 15","source":"act","popular":true,"keywords":"monetary settlement compensation damages payment conciliation money"},{"id":"applicable-procedure","topic":"Inquiry and evidence","question":"Should every Committee use the Central Rules in exactly the same way?","answer":["Section 11(1) requires attention to the service rules applicable to an employee respondent and the prescribed procedure where such rules do not exist. Sector, institutional and jurisdictional frameworks can therefore matter.","The Central Rules references in this overview are qualified where applicable. They do not replace checking the governing procedure for a live case."],"basis":"Section 11(1)","source":"act","popular":false,"keywords":"service rules central rules government private sector"},{"id":"ninety-day-inquiry","topic":"Inquiry and evidence","question":"Which provision gives the inquiry its 90-day limit?","answer":["Section 11(4) sets the inquiry-completion period at ninety days. Section 11(1) concerns the inquiry framework and contains additional safeguards; it is not the subsection that states the ninety-day limit.","The overview separates those references deliberately. Do not interpret the lack of a separate deadline for every individual hearing or evidence step as permission to ignore the overall period."],"basis":"Section 11(1) and Section 11(4)","source":"act","popular":false,"keywords":"90 days stage 5 duration timeline"},{"id":"appreciation-evidence","topic":"Inquiry and evidence","question":"What does appreciation of evidence mean?","answer":["It means considering what the available material establishes, including its relevance, reliability, consistency and weight in the particular inquiry. Witness examination and appreciation of evidence are related but not identical activities.","It is not a mechanical score, a count of documents or an automatic finding of guilt. The free overview neither evaluates a person’s credibility nor produces findings for a live case."],"basis":"Section 11; natural justice under applicable Central Rule 7(4)","source":"act","popular":false,"keywords":"evaluation assessment proof witness credibility scoring"},{"id":"absence-ex-parte","topic":"Inquiry and evidence","question":"Does missing a hearing automatically mean an ex-parte decision or guilt?","answer":["No. Applicable Central Rule 7(5) addresses three consecutive hearing absences without sufficient cause and requires written notice fifteen days in advance before termination or an ex-parte order.","The safeguard does not equate absence with proof of guilt. Actual notice, reasons and governing procedure still matter."],"basis":"Central Rule 7(5)","source":"rules","popular":false,"keywords":"absent missed hearing ex parte default 15 days"},{"id":"hearing-quorum","topic":"Inquiry and evidence","question":"How many Committee members must attend an inquiry hearing?","answer":["Applicable Central Rule 7(7) requires at least three members, including the Presiding Officer or Chairperson. Attendance at a hearing is different from the Committee’s overall constitution.","A checkbox or website statement cannot validate the constitution, membership or attendance of a real Committee."],"basis":"Central Rule 7(7); Sections 4 and 7","source":"rules","popular":false,"keywords":"quorum three members presiding chairperson"},{"id":"lawyer-representation","topic":"Inquiry and evidence","question":"Can a lawyer represent a party before the Committee?","answer":["Central Rule 7(6), where applicable, bars representation by a legal practitioner in proceedings before the Committee. Verify the governing service-rule and procedural framework.","Distinguish representation in the hearing from seeking independent legal advice outside it."],"basis":"Central Rule 7(6); Section 11(1)","source":"rules","popular":false,"keywords":"advocate lawyer assistance representative"},{"id":"interim-relief","topic":"Inquiry and evidence","question":"Must a woman wait for the final report before asking for protection?","answer":["No. Section 12 provides a route for interim recommendations on the aggrieved woman’s written request while inquiry is pending. It includes transfer-related relief and up to three months of additional leave; applicable Rule 8 addresses certain reporting or supervision arrangements.","These are not automatic outcomes or findings against the respondent. The competent Committee and employer have their respective statutory roles."],"basis":"Section 12; Central Rule 8","source":"act","popular":false,"keywords":"interim safety transfer leave appraisal supervisor retaliation"},{"id":"constitution-versus-quorum","topic":"Inquiry and evidence","question":"Does a three-member hearing mean a three-member IC is enough?","answer":["No. IC constitution under Section 4 requires a woman Presiding Officer, at least two employee members and one qualifying external member; at least half of the nominated members must be women. This differs from the hearing-attendance rule.","Applicable Central Rule 7(7) requires at least three members, including the Presiding Officer or Chairperson, at an inquiry. Do not treat that hearing minimum as permission to omit the external member from the constituted IC. LC composition is separately governed by Section 7."],"basis":"Section 4(2); Section 7; applicable Central Rule 7(7)","source":"act","popular":false,"keywords":"three four members external quorum women constitution attendance"},{"id":"no-eyewitness","topic":"Inquiry and evidence","question":"Must I have CCTV footage or an eyewitness before making a complaint?","answer":["Do not assume that a complaint is impossible without CCTV or an eyewitness. A written account and any lawfully available supporting material can be relevant; what they establish must be assessed fairly in the particular inquiry.","Preserve original records without altering them or obtaining unauthorised access. The absence of one type of evidence does not let this website decide whether an allegation is proved, unproved or malicious."],"basis":"Sections 9, 11 and 14; applicable procedure","source":"act","popular":false,"keywords":"CCTV eyewitness witness screenshot recording proof evidence"},{"id":"retaliation-all-stakeholders","topic":"Inquiry and evidence","question":"How should complainants, respondents, witnesses and Committee members be protected from retaliation?","answer":["A fair institutional process should prohibit threats, coercion, victimisation and interference against anyone participating, including parties, witnesses, Committee and external members, and people giving legitimate assistance. Preserve relevant records and report concerns promptly through an appropriate, independent channel.","Section 19(a) concerns employer provision of a safe working environment; natural-justice safeguards also matter. Section 12 interim relief specifically concerns the aggrieved woman’s written request and is not a blanket remedy available identically to every stakeholder. If the usual recipient is implicated, seek an unconflicted competent route; urgent threats may require police or emergency assistance. Safeguards do not presume either party guilty."],"basis":"Section 19(a); Section 12; applicable Central Rule 7(4); institutional non-retaliation policy","source":"act","popular":false,"keywords":"retaliation safety victimisation witness respondent committee intimidation threats"},{"id":"findings-representation","topic":"Findings, reports and remedies","question":"Why should parties receive findings before the completed report stage?","answer":["The second proviso to Section 11(1) provides, where both parties are employees, for an opportunity to be heard and access to findings so they can make representations against them before the Committee.","This safeguard is distinct from giving the concerned parties the completed report under Section 13(1). Section 11(1) itself does not set a universal number of days for making those representations."],"basis":"Section 11(1), second proviso; Section 13(1)","source":"act","popular":false,"keywords":"preview findings representation draft report same employees stage 7"},{"id":"report-ten-days","topic":"Findings, reports and remedies","question":"When must the completed inquiry report be supplied?","answer":["Section 13(1) requires the Committee to provide its report to the employer or District Officer within ten days of inquiry completion and make it available to the concerned parties.","This ten-day report requirement must not be confused with the respondent’s ten-working-day reply provision or a supposed universal ten-day findings-representation period."],"basis":"Section 13(1); Central Rule 7(3)","source":"act","popular":false,"keywords":"10 days final report copy parties"},{"id":"action-sixty-days","topic":"Findings, reports and remedies","question":"Does the Committee itself carry out every final recommendation?","answer":["Section 13(4) requires the employer or District Officer to act on the recommendations within sixty days of receipt. The Committee’s report and the authority’s implementation are separate events.","Keep the actual report-delivery and action records. Neither a downloaded draft nor a community answer establishes that a recommendation has been implemented."],"basis":"Section 13(4)","source":"act","popular":false,"keywords":"60 days implementation employer district officer"},{"id":"unproved-not-malicious","topic":"Findings, reports and remedies","question":"Does an unproved complaint automatically become a false or malicious complaint?","answer":["No. Section 14 distinguishes inability to substantiate a complaint or provide adequate proof from the conditions for action concerning malicious or knowingly false complaints and false evidence. Malicious intent must be established through the prescribed process.","Neither an adverse outcome nor a disputed account should automatically trigger a finding of malice. This website makes no such determination."],"basis":"Section 14","source":"act","popular":false,"keywords":"false complaint malice insufficient evidence not proved retaliation"},{"id":"appeal-forum","topic":"Findings, reports and remedies","question":"Can I appeal, and does the website file it for me?","answer":["Section 18 provides an appeal route for the specified recommendations, penalties or non-implementation, with a ninety-day period from the recommendations. The proper court, tribunal or prescribed authority and applicable service rules require verification.","This website is not an appeal portal. An email, draft or community post here does not lodge an appeal or protect a limitation period."],"basis":"Section 18; applicable Central Rule 11","source":"act","popular":false,"keywords":"90 days appeal tribunal challenge non implementation","related":["appeal-ic-to-lc","action-sixty-days"]},{"id":"police-and-inquiry","topic":"Findings, reports and remedies","question":"Does a POSH inquiry replace a police complaint or criminal proceedings?","answer":["No. Section 28 makes the Act additional to other laws. A workplace inquiry and criminal proceedings have different purposes and legal standards; one is not automatically a substitute for the other.","Seek appropriate advice on available routes and current criminal law. This website does not register a police complaint, contact authorities or decide how parallel proceedings should be managed."],"basis":"Sections 19 and 28","source":"act","popular":false,"keywords":"police FIR criminal parallel proceedings"},{"id":"annual-versus-inquiry-report","topic":"Findings, reports and remedies","question":"Is the Committee’s annual report the same as an individual inquiry report?","answer":["No. The inquiry report under Section 13 concerns a particular complaint. The annual reporting duties under Sections 21 and 22 concern periodic reporting and employer disclosures.","Applicable Central Rule 14 specifies annual-report information such as complaint counts and awareness activities. These duties do not authorise public disclosure of confidential case files. This staging site neither files annual reports nor certifies organisational compliance."],"basis":"Sections 13, 16, 21 and 22; applicable Central Rule 14","source":"act","popular":false,"keywords":"annual report compliance calendar reporting employer"},{"id":"anonymous-community","topic":"Community and privacy","question":"Is the community completely untraceable?","answer":["No account, name, email address or phone number is requested for public posting. Generated aliases are attached separately to posts. That provides anonymity to other readers; it is not a promise of complete untraceability.","Hosts may process technical logs, and the application uses short-lived network fingerprints for basic limits. Free text can still identify you or someone else. Keep real case facts and identifying details out of posts."],"basis":"Current community privacy design","source":"community","popular":false,"keywords":"anonymous phone name IP privacy identity logs"},{"id":"community-review","topic":"Community and privacy","question":"Why is my question or answer not visible immediately?","answer":["Every question and answer enters a private pending-review queue. Only approved content becomes public, and each answer needs its own approval. Review is not a legal endorsement or a guarantee of response time.","Save your receipt if you need to refer to a submission. There are no member accounts, self-edit controls or email notifications in this version."],"basis":"Current moderation workflow","source":"community","popular":false,"keywords":"pending approval delay receipt no sign in"},{"id":"confidential-case-post","topic":"Community and privacy","question":"Can I upload my complaint, evidence or an NDA to get advice?","answer":["No. The community is for general discussion. Do not share names, employers, witness identities, phone numbers, detailed allegations, confidential documents or material that could identify a case.","There are no attachments or direct messages. Use the competent authority’s appropriate channels for case material; community moderation does not turn a public forum into a confidential professional consultation."],"basis":"Community boundaries; Section 16","source":"community","popular":false,"keywords":"upload documents case files evidence NDA personal details"},{"id":"community-answer-authority","topic":"Community and privacy","question":"Is a moderator-approved answer verified legal advice?","answer":["No. Generated aliases do not establish anyone’s identity, qualifications or authority. Approval is a publication-review decision, not confirmation that an answer is legally correct or suitable for your circumstances.","Check primary sources and obtain appropriate professional advice before acting on a particular matter. The platform does not appoint a Committee or contact authorities on your behalf."],"basis":"Community contribution status","source":"community","popular":false,"keywords":"expert lawyer verified advice official moderator"},{"id":"report-remove-post","topic":"Community and privacy","question":"How can I flag a post or ask for removal?","answer":["Use Report on an approved question or answer and choose the relevant reason. Reports go to private review. A moderator can edit, reject or hide content; hiding a question also makes its answers unavailable while the parent is not approved.","No member login or self-service editing/deletion account exists. Do not post additional identifying information to explain a removal request publicly."],"basis":"Current reporting and moderation workflow","source":"community","popular":false,"keywords":"delete edit remove report abuse privacy"},{"id":"free-versus-paid","topic":"Plans and using the site","question":"What is free, and what remains part of the planned paid platform?","answer":["The free offering includes both individual guidance journeys, editable local Word drafts, the basic nine-stage inquiry overview, this FAQ and the moderated community.","Detailed IC/LC case management, confidential case records, hearing tools, professional inquiry findings/report generation and NDA acknowledgement tracking are planned professional capabilities. A public FAQ explanation is not access to those tools.","The planned catalogue distinguishes Essential’s core procedural workspace from Professional’s full 44-section report builder, evidence/annexure indexes and three readiness reviews; Advanced adds complex-case and challenge tools. Institutional Plus and Government / Enterprise add agreed configuration and support. Every paid tier keeps the legally necessary core safeguards; availability still depends on completed implementation and activation."],"basis":"Current product scope","source":"plans","popular":false,"keywords":"free demo paid limits IC LC professional workspace"},{"id":"plan-users-duration","topic":"Plans and using the site","question":"What do the plan duration, user count and read-only period mean?","answer":["The planned case licences show a working period and a maximum authorised-user count: Essential six months/two users, Professional nine months/five users, Advanced twelve months/eight users and Institutional Plus twelve months/fifteen users.","The four listed paid licences include three additional read-only months and one-authorised-proceeding scope, subject to written terms. Read-only time does not promise continued editing, new case work or an automatic renewal. Government/Enterprise terms are contractual."],"basis":"Current commercial specification","source":"plans","popular":false,"keywords":"licence license users duration access read only multiple cases"},{"id":"institutional-price-tax","topic":"Plans and using the site","question":"Is Institutional Plus exactly ₹1,49,999 including GST?","answer":["The published price remains from ₹1,49,999. Institutional Plus requires an agreed proposal; applicable GST is additional. Government/Enterprise is custom-quoted.","Do not treat the displayed starting price as a final tax-inclusive invoice or an unlimited multi-case entitlement. Scope, authorised users, continuity, activation and other commercial terms must be agreed in writing."],"basis":"Current pricing and licence boundaries","source":"plans","popular":false,"keywords":"149999 1,49,999 Institutional Plus GST taxes quotation"},{"id":"payment-test-mode","topic":"Plans and using the site","question":"Is Razorpay connected, and will a test payment activate a plan?","answer":["Actual Razorpay testing is pending the owner’s test credentials. Without those credentials, checkout is disabled. The staging integration refuses live keys and is designed only for simulated test transactions.","A test transaction creates no real purchase, tax invoice, paid account or service entitlement. Do not enter real payment details into a test flow. Institutional and Government/Enterprise purchases still require a proposal or quotation."],"basis":"Current staging payment status","source":"plans","popular":false,"keywords":"Razorpay payment gateway test keys activation refund invoice"},{"id":"draft-not-filed","topic":"Plans and using the site","question":"Has downloading a complaint or reply filed or served it?","answer":["No. The Word file is generated locally as an editable draft using the relevant selections you supplied. Review and complete it, verify the appropriate route, and submit or serve it independently through an appropriate channel.","The platform does not email the document to an IC, LC, employer, police or court. It cannot confirm submission, receipt, acknowledgement, legal acceptance or service."],"basis":"Current document-generation boundary","source":"guidance","popular":false,"keywords":"DOCX Word download filing submission served acknowledged"},{"id":"urgent-support","topic":"Plans and using the site","question":"Can I rely on the FAQ or community for urgent safety or child-protection action?","answer":["No. They are not emergency, reporting or crisis-response channels, and nobody is contacted automatically. Seek appropriate local emergency, police, child-protection or professional assistance directly when circumstances require it.","A concern involving a child can engage separate legal duties and safeguards. Do not put a child’s identity or detailed statement into the community. The free guidance is preliminary and cannot carry out mandatory reporting for you."],"basis":"Safety boundary; separate child-protection duties","source":"guidance","popular":false,"keywords":"emergency child minor urgent police POCSO reporting"},{"id":"suggest-faq","topic":"Plans and using the site","question":"Can I suggest another question for this FAQ?","answer":["Yes. Use “Suggest a future FAQ” below to submit a general question through the existing anonymous moderated community. No sign-in, name or contact number is requested. Keep all identifying and confidential facts out of it.","Submission is for review, not automatic addition to the FAQ. An editor must verify the answer and relevant sources before publishing a new FAQ; no response or publication time is promised. The community is not a formal complaint or confidential advice channel."],"basis":"Editorial process; anonymous pre-publication moderation","source":"community","popular":false,"keywords":"suggest new question add FAQ request feedback future"},{"id":"all-women-workforce","topic":"IC and LC constitution","question":"We have only women workers. Do we still need an IC?","answer":["Yes, an all-women workforce is not an exemption from the IC requirement for a workplace with ten or more workers. The headcount is not limited to male workers. A workplace may also be visited by women who are not its employees.","Constitute the Committee lawfully and maintain prevention, awareness and reporting arrangements. Do not assume that workforce gender makes harassment impossible or removes employer duties."],"basis":"Sections 2, 4, 6 and 19","source":"act","popular":true,"keywords":"100 percent female women workforce ten 10 workers"},{"id":"all-men-workforce","topic":"IC and LC constitution","question":"We have only men workers. Do we still need an IC?","answer":["An all-men workforce does not exempt a workplace with ten or more workers from constituting an IC. The Act protects an aggrieved woman whether employed at the workplace or not, so visitors and other work connections can matter.","Do not appoint a male Presiding Officer simply because no woman works at that office. Follow the statutory fallback sequence for a woman Presiding Officer and seek competent assistance with a compliant constitution."],"basis":"Sections 2(a), 4(2)(a) and 6","source":"act","popular":false,"keywords":"100 percent male men workers women employee no woman"},{"id":"no-presiding-officer","topic":"IC and LC constitution","question":"We have no senior woman employee to appoint as Presiding Officer. What can we do?","answer":["Section 4(2)(a) provides a sequence: first a woman employee at a senior level in the workplace; if unavailable, nominate from other offices or administrative units. If those also lack a senior woman employee, the further proviso permits nomination from another workplace of the same employer or another department or organisation.","Record the actual circumstances and verify the proposed appointment against the provision and applicable framework. This is not permission to appoint any outside consultant without review, to substitute a male chair, or to leave a required IC unconstituted."],"basis":"Section 4(2)(a) and its two provisos","source":"act","popular":true,"keywords":"PO presiding officer no senior woman female employee outside organisation"},{"id":"multiple-branches-ic","topic":"IC and LC constitution","question":"Can one head-office IC automatically cover every branch?","answer":["Section 4(1)’s proviso addresses offices or administrative units at different places or divisional or sub-divisional levels and requires constitution at those units or offices. Do not assume a single head-office order automatically satisfies the requirement for every location.","Review the actual structure, workforce and applicable directions for each workplace with the competent authority. Constitution of Committees and recording branches on SHe-Box are related compliance tasks, but portal registration does not itself create a valid IC."],"basis":"Section 4(1), proviso; Section 6","source":"act","popular":false,"keywords":"branches head office separate IC locations multi location"},{"id":"who-constitutes-lc","topic":"IC and LC constitution","question":"Can an employer appoint its own Local Committee instead of an IC?","answer":["No. The District Officer constitutes the district LC under Sections 6 and 7. It is not a company committee an employer creates to avoid the IC requirement.","LC jurisdiction includes the statutory routes for establishments with fewer than ten workers and complaints against the employer. Confirm the competent receiving route, including when an IC is absent or defective, without letting the complaint window lapse."],"basis":"Sections 5, 6 and 7","source":"act","popular":false,"keywords":"LC local committee district officer employer appoint small workplace"},{"id":"committee-tenure-vacancies","topic":"IC and LC constitution","question":"Can an IC appointment continue indefinitely, or can we ignore a vacancy?","answer":["Section 4(3) limits the specified term of the IC Presiding Officer and members to no more than three years from nomination. Section 4(5) addresses specified removal grounds and filling vacancies by fresh nomination.","Maintain current written orders and contact details rather than relying on an expired list. The effect of a resignation, conflict, expiry or reconstitution on a pending inquiry needs proper procedural review; the website does not automatically validate or invalidate past proceedings."],"basis":"Sections 4(3), 4(5) and 19","source":"act","popular":false,"keywords":"tenure three 3 years resignation vacancy conflict replacement","related":["ic-reappointment-three-years","committee-change-continuity"]},{"id":"awareness-training-mandatory","topic":"IC and LC constitution","question":"Are POSH awareness sessions and IC training legally required?","answer":["Yes. Section 19(c) requires employer workshops and awareness programmes at regular intervals for employees and orientation programmes for IC members, in the prescribed manner. Applicable Central Rule 13 also addresses policy dissemination, orientation, awareness and capacity building.","The cited provisions do not set one universal annual session count or prescribe this website’s commercial course. Check sector and local requirements, plan suitable recurring training and retain accurate records. A certificate or one session alone does not establish complete POSH compliance."],"basis":"Section 19(c); applicable Central Rule 13","source":"rules","popular":false,"keywords":"awareness mandatory training sensitisation orientation annual frequency workshop"},{"id":"external-member-eligibility","topic":"External members and fees","question":"What qualifies someone to be an IC external member?","answer":["Section 4(2)(c) permits a member from an NGO or association committed to the cause of women, or a person familiar with issues relating to sexual harassment. Relevant knowledge and suitability must be established. Neither a law degree, HR title, trainer certificate nor SHe-Box empanelment alone proves eligibility.","Check and record the person’s qualifying background and independence, including relationships with the employer, parties and events. A government certificate or advocate status is not a universal IC requirement. Do not import Central Rule 4’s LC-specific qualification examples as a mandatory five-year requirement for every IC external member."],"basis":"Section 4(2)(c); distinguish Section 7 and Central Rule 4","source":"act","popular":true,"keywords":"external member qualification NGO lawyer trainer eligibility IC experience","related":["lc-member-expertise","member-conflict-interest","external-member-absence"]},{"id":"lc-member-expertise","topic":"External members and fees","question":"Does every IC external member need five years of social-work experience?","answer":["Do not transfer the LC rule indiscriminately to the IC. Central Rule 4 concerns the person familiar with sexual-harassment issues for Section 7(2)(c), and includes examples such as a social worker with at least five years of relevant experience or a person familiar with labour, service, civil or criminal law.","IC external-member eligibility instead begins with Section 4(2)(c). Review the correct role, statutory wording and applicable rules before choosing a candidate. A brief course or a claimed title is not a substitute for assessing suitability."],"basis":"Central Rule 4; Sections 4(2)(c) and 7(2)(c)","source":"rules","popular":false,"keywords":"five 5 years social worker expertise LC IC external qualification"},{"id":"external-member-gender","topic":"External members and fees","question":"Must the IC external member be a woman or an advocate?","answer":["Section 4(2)(c) does not prescribe either condition for that individual role. The candidate must meet its eligibility route, while the Committee as a whole must have at least half women members and a woman Presiding Officer.","An advocate acting as a Committee member is different from a lawyer representing a party. Independence, conflicts and the applicable procedure still require review; do not treat professional status as automatic qualification."],"basis":"Section 4(2); distinguish applicable Central Rule 7(6)","source":"act","popular":false,"keywords":"external male female gender advocate lawyer woman half"},{"id":"ic-external-member-fees","topic":"External members and fees","question":"Must we pay the IC external member? Is the fee only ₹200?","answer":["Section 4(4) and applicable Central Rule 3 address employer-paid fees or allowances. Rule 3 specifies ₹200 per day for the member appointed from an NGO for holding IC proceedings, together with prescribed travel reimbursement. The employer bears these costs.","Distinguish that statutory provision and its scope from a quoted professional retainer, training fee or other service contract. Do not describe ₹200 as a universal commercial package price or a blanket ceiling for every appointment. Check applicable rules and record lawful fee, travel and additional-service terms in writing."],"basis":"Section 4(4); Central Rule 3","source":"rules","popular":true,"keywords":"external member payout payment remuneration fees 200 rupees honorarium travel retainer","related":["lc-member-fees","external-member-eligibility"]},{"id":"lc-member-fees","topic":"External members and fees","question":"Are LC member fees the same as IC external-member fees?","answer":["No. Applicable Central Rule 5 specifies ₹250 per day for the LC Chairperson and eligible members, with the stated exclusions for members nominated under Section 7(2)(b) and (d), and prescribed travel reimbursement. The District Officer bears the specified costs.","This is distinct from the IC provision in Rule 3. Verify the particular member category and any governing revised rules before applying an amount; an LC allowance is not a universal private-consultant tariff."],"basis":"Central Rule 5; Section 7(4); distinguish Rule 3","source":"rules","popular":false,"keywords":"LC local chairperson member payout fees 250 district officer"},{"id":"shebox-registration-duty","topic":"SHe-Box and nodal officers","question":"Is SHe-Box registration mandatory, or can we treat it as optional?","answer":["Do not rely on a blanket “optional” answer. Court-led implementation and official directions require collection and onboarding of IC/LC data. MWCD’s 2026 parliamentary replies describe surveys of public and private workplaces and uploading the collected details. Local notices can expressly direct employer registration; Delhi is one example.","Check the current direction for each State, district and sector, and complete the applicable organisation, branch, nodal-officer and Committee records. The portal workflow is not the source of the IC constitution duty itself. This website does not verify your organisation’s registration or certify compliance."],"basis":"MWCD parliamentary replies, 6 February and 1 April 2026; applicable local notices","source":"sheboxCompliance","popular":true,"keywords":"SHe Box SheBox mandatory registration optional compliance portal","related":["shebox-two-branches","shebox-nodal-officer-who","shebox-not-ic"]},{"id":"shebox-two-branches","topic":"SHe-Box and nodal officers","question":"We have a head office and two branches. Do both branches need SHe-Box entries?","answer":["Do not assume that registering only the head office records all workplaces. Use the official Private Head Office Registration route for a private head office, then follow the current head-office manual and linked branch/workplace process to record both branch locations and the relevant nodal-officer and IC details.","Verify that each branch appears correctly and obtain District Nodal Officer or portal-support guidance for any mapping or account issue. Avoid duplicate unrelated head-office registrations unless officially directed. Exact screens and role/email constraints can change; the direct current portal/manual could not be independently loaded during this review."],"basis":"Section 4(1); current official private-head-office manual and local directions","source":"sheboxManual","popular":true,"keywords":"two 2 branches head office private registration workplace branch office dashboard"},{"id":"shebox-nodal-officer-who","topic":"SHe-Box and nodal officers","question":"Who should be appointed as our SHe-Box Nodal Officer?","answer":["Designate an authorised, responsible person through a written organisational decision, subject to the current portal and applicable directions. As a practical selection criterion, the person should be able to monitor official communications, coordinate with the IC and authorities, keep records current and protect confidentiality.","Do not assume that the Presiding Officer’s statutory qualification automatically applies to this separate portal role, or that the Nodal Officer becomes the inquiry decision-maker. Confirm current eligibility and account-role restrictions with the portal or District Nodal Officer; a particular job title or dual-role arrangement is not certified here."],"basis":"Portal-role guidance; distinguish Section 4(2)(a) and statutory Committee powers","source":"sheboxManual","popular":false,"keywords":"nodal officer HR compliance legal authorised person eligibility male female appoint"},{"id":"shebox-nodal-role","topic":"SHe-Box and nodal officers","question":"What does a SHe-Box Nodal Officer do?","answer":["The operational role is coordination: monitor authorised portal communications, keep organisation and Committee information current, route matters promptly to the competent Committee, track required updates and liaise with the appropriate authority. Limit access and disclosures to what the role lawfully requires.","The Nodal Officer must not independently decide merits, alter Committee findings or suppress a complaint. The precise dashboard powers and reporting tasks depend on the current assigned portal role and official directions; appointment does not replace the IC, LC or employer’s statutory duties."],"basis":"SHe-Box role guidance; Sections 4, 6, 11, 13 and 19","source":"sheboxManual","popular":false,"keywords":"nodal officer role responsibilities monitoring coordination reports privacy"},{"id":"portal-versus-statutory-nodal","topic":"SHe-Box and nodal officers","question":"Is a company’s SHe-Box Nodal Officer the same as the officer under Section 6(2)?","answer":["No. Section 6(2) concerns District Officer-designated nodal officers in specified local areas to receive complaints and forward them to the LC within seven days. A company portal coordinator is a different role.","Also distinguish the District Officer under Section 5 and the portal’s State/District Nodal Officer labels. Ask which capacity an official or employee is acting in; similarly named roles do not automatically have identical powers."],"basis":"Sections 5 and 6(2); SHe-Box role distinction","source":"act","popular":false,"keywords":"nodal officer block taluka tehsil ward municipality seven days district company"},{"id":"shebox-trainer-directory","topic":"SHe-Box and nodal officers","question":"Where can we find the SHe-Box empanelled trainers or organisations list?","answer":["Start from the official SHe-Box website and its Empanelment or resource-directory area, using the current approved list available there. Verify the exact individual or organisation, scope and current status before engaging anyone; do not rely solely on an old copied PDF or a provider’s badge.","The live directory could not be independently opened during this review, so this FAQ does not present a current verified roster or recommend a named provider. If the list is unavailable, use the portal’s official contact/support route or MWCD for the current approved directory."],"basis":"Official SHe-Box portal; MWCD empanelment programme","source":"shebox","popular":false,"keywords":"empaneled empanelled trainers training resource directory list approved institutes"},{"id":"empanelment-versus-eligibility","topic":"SHe-Box and nodal officers","question":"Does SHe-Box trainer empanelment automatically qualify someone as an IC external member?","answer":["No. Training empanelment, IC external-member eligibility and LC membership are different questions. Section 4(2)(c) is the starting point for the IC external role; relevant LC eligibility comes from Section 7 and the applicable rules.","Verify the person’s actual eligibility, competence, independence and conflicts for the proposed appointment. Neither a SHe-Box entry nor a training certificate alone is a statutory appointment or a guarantee of suitability."],"basis":"Sections 4(2)(c) and 7; distinguish trainer empanelment","source":"act","popular":false,"keywords":"empanelment automatic external member qualification trainer certificate mandatory"},{"id":"shebox-not-ic","topic":"SHe-Box and nodal officers","question":"Does registering on SHe-Box create our IC or replace its written constitution order?","answer":["No. A portal account or data entry is not the written constitution required by Section 4. The Committee must have valid appointments and satisfy the applicable composition requirements.","Keep the constitution order, actual membership, contact details and portal records consistent. A registration receipt is not a legal finding that the Committee or an inquiry is valid. This Navigator is independent of SHe-Box and does not register a workplace."],"basis":"Section 4; distinction between constitution and portal record","source":"act","popular":false,"keywords":"registration creates IC certification constitution written order SHe Box"},{"id":"shebox-updates-and-delays","topic":"SHe-Box and nodal officers","question":"What if SHe-Box approval is delayed or our Committee details change?","answer":["Keep records of the submission, current constitution order and attempts to contact the relevant District Nodal Officer or official support. Follow the current portal process to correct or update records and avoid creating conflicting duplicates.","Portal delay does not suspend the employer’s duties or a complainant’s statutory window. Keep lawful receiving channels available and verify proper complaint routing with the competent authority. Do not post registration documents, passwords or case details in this public community."],"basis":"Sections 4, 9 and 19; current portal support process","source":"shebox","popular":false,"keywords":"pending approval delay update IC nodal officer change password registration support"},{"id":"when-police-referral","topic":"Police, BNS and appeals","question":"When can a POSH matter involve police or criminal proceedings?","answer":["A POSH inquiry is not a criminal trial. Conduct may also disclose an offence under the applicable criminal law, in which case police and criminal-court routes need separate consideration. A Committee does not convict anyone under the BNS or automatically convert every POSH complaint into an FIR.","Section 11(1) contains a specific LC police-referral route for domestic workers where a prima facie case exists, and its first proviso addresses breach of a recorded conciliation settlement. Section 19(g) requires employer assistance if the woman chooses to complain under criminal or other applicable law; Section 19(h) separately addresses initiation of action in its stated circumstances. Section 28 preserves other legal routes.","Identify the facts, any immediate danger or mandatory reporting duty, and the law applicable to the incident. Seek competent assistance; this website neither chooses criminal charges nor sends a referral."],"basis":"Sections 11(1), 19(g)–(h) and 28; applicable criminal law","source":"act","popular":true,"keywords":"criminal referral BNS police FIR committee prosecution"},{"id":"domestic-worker-police","topic":"Police, BNS and appeals","question":"What is the domestic-worker police-referral rule, and is it seven working days?","answer":["Section 11(1) provides that, in the case of a domestic worker, the LC shall, if a prima facie case exists, forward the complaint to police within seven days. The provision says days, not working days. This is distinct from Central Rule 7(2)’s seven-working-day complaint-copy service rule.","The POSH statutory text refers to IPC Section 509 and other relevant IPC provisions. Current-law application requires checking the incident date and the IPC/BNS transition; do not silently substitute a section number or assume the Committee decides criminal guilt."],"basis":"Section 11(1), domestic-worker limb; distinguish Central Rule 7(2)","source":"act","popular":false,"keywords":"domestic worker house help maid police seven 7 days working"},{"id":"ipc-to-bns","topic":"Police, BNS and appeals","question":"The POSH Act mentions the IPC. Should we now write BNS in every case?","answer":["Not mechanically. The BNS generally commenced on 1 July 2024, subject to its notified exception, and its Section 358 contains repeal-and-savings provisions. The incident date, any continuing conduct and the legal transition must be checked; an older matter is not automatically relabelled solely because it is reported now.","BNS Section 75 concerns specified sexual-harassment acts by a man; Sections 74 and 76–79 address other specified conduct against women. Each offence has its own ingredients. The police or a qualified professional must identify applicable provisions; a POSH finding does not automatically establish a BNS offence. BNS defines offences, while police receive/investigate and courts determine criminal liability."],"basis":"BNS Sections 74–79 and 358; commencement notification; POSH Sections 11, 19 and 28","source":"bns","popular":false,"keywords":"BNS IPC 509 79 75 criminal July 2024 transition old new law"},{"id":"appeal-ic-to-lc","topic":"Police, BNS and appeals","question":"Can I appeal an IC decision to the LC?","answer":["No. The LC is not an appellate body over the IC. Its original complaint jurisdiction under Section 6 must not be confused with the appeal route under Section 18.","For the specified recommendations or non-implementation, Section 18 directs an appeal through the applicable service-rule court/tribunal route or prescribed procedure where such rules do not exist. Applicable Central Rule 11 also needs checking. Section 18(2) states ninety days from the recommendations; confirm the competent forum and exact route promptly. Writing to the LC should not be assumed to preserve an appeal deadline."],"basis":"Sections 6 and 18; applicable Central Rule 11","source":"act","popular":true,"keywords":"appeal IC LC appellate authority court tribunal ninety 90 days"},{"id":"police-before-final-report","topic":"Police, BNS and appeals","question":"Must we finish the IC inquiry before anyone can approach police?","answer":["Do not treat completion of the workplace inquiry as a universal precondition to reporting a suspected crime. Section 28 preserves other laws, and employer assistance under Section 19(g) is distinct from the IC’s report under Section 13.","Any statutory mandatory-reporting duties, including applicable child-protection duties, need separate attention. Parallel proceedings, confidentiality and evidence preservation require competent handling; neither an IC settlement nor this FAQ guarantees that criminal proceedings stop."],"basis":"Sections 13, 19(g) and 28; separate mandatory-reporting duties","source":"act","popular":false,"keywords":"police first wait final report parallel crime child mandatory reporting"},{"id":"employer-noncompliance","topic":"Employer compliance and consequences","question":"What are the consequences of not complying with the POSH Act?","answer":["Section 26(1) provides a fine up to ₹50,000 for specified employer failures, including not constituting the required IC, failing to take the listed actions, and contravening or abetting contravention of other provisions or rules. This is a statutory maximum, not an automatic flat charge imposed by this website.","Where an employer has a previous conviction and is subsequently convicted of the same offence, Section 26(2) provides enhanced punishment and licence/registration-related consequences under its terms. Do not describe every lapse as automatic closure or assume paying a fine removes the compliance duty. Actual proceedings, facts, other applicable law and the competent authority matter."],"basis":"Sections 25, 26 and 27","source":"act","popular":true,"keywords":"penalty fine 50000 50 000 consequences employer noncompliance repeat offence licence cancellation"},{"id":"missing-awareness-consequences","topic":"Employer compliance and consequences","question":"What if the employer does not organise awareness sessions or IC orientation?","answer":["These are duties under Section 19(c), read with applicable Central Rule 13. Failure can engage Section 26’s non-compliance provisions; there is not a separate universal automatic ₹50,000 fine for each missed session stated in these provisions.","Arrange appropriate recurring awareness and role-specific orientation, keep truthful attendance/material records and address gaps promptly. Do not backdate certificates or treat a later workshop as erasing earlier non-compliance. Check applicable local and sector directions; the Act’s phrase regular intervals does not itself prescribe one universal annual session count."],"basis":"Section 19(c); Central Rule 13; Section 26","source":"act","popular":false,"keywords":"awareness orientation no session failure penalty training consequences mandatory regular intervals"},{"id":"ic-reappointment-three-years","topic":"IC and LC constitution","question":"Can the same IC member or Presiding Officer be appointed again after three years?","answer":["A fresh appointment can be considered: Section 4(3) caps the specified term of a nomination at three years; it does not expressly impose a once-only lifetime bar. This is not an automatic extension of the old order. Check applicable service, institutional and sector rules before a fresh written nomination.","Recheck current eligibility, independence, conflicts, the required positions and women’s representation. Do not backdate an order to cover an expired appointment or assume that a pending inquiry extends the term. The effect on an ongoing matter needs a documented continuity review."],"basis":"Sections 4(1)–(3) and 4(5)","source":"act","keywords":"repeat repeated renew renewal renomination reappointment 3 years three term tenure","popular":false,"related":["committee-tenure-vacancies","committee-change-continuity"]},{"id":"po-personal-absence","topic":"IC and LC constitution","question":"What if the Presiding Officer is unavailable during an inquiry for personal reasons?","answer":["Record whether the absence is temporary or whether there is a vacancy or need for lawful replacement. Under applicable Central Rule 7(7), at least three members including the Presiding Officer or LC Chairperson must be present when conducting the inquiry. Do not simply let another member act as chair to bypass that requirement.","For temporary unavailability, arrange a prompt, properly notified date with valid participation; for a longer-term change, use the lawful nomination/reconstitution route and review continuity. Record reasons, service and the impact on deadlines. Personal absence does not itself pause the statutory inquiry clock."],"basis":"Section 4; Section 11(4); applicable Central Rule 7(7)","source":"rules","keywords":"leave illness medical personal reason absent presiding officer vacation substitute acting chair","popular":false,"related":["ordinary-member-absence","committee-change-continuity"]},{"id":"ordinary-member-absence","topic":"Inquiry and evidence","question":"Can an inquiry proceed if an ordinary IC member is on leave or absent?","answer":["A single ordinary member’s temporary absence does not by itself answer whether a hearing is valid. Check the continuing lawful constitution, the applicable procedure and required attendance. Central Rule 7(7), where applicable, sets a minimum of three members including the Presiding Officer or Chairperson.","Record who attended each event, the reason for absence where appropriate, and whether members deciding the matter have a fair basis to assess the material. Recalls or further opportunity may be needed under the governing framework. Do not assume that an absent member can automatically sign off on evidence they never properly considered."],"basis":"Sections 4 and 11; applicable Central Rule 7(4), (7)","source":"rules","keywords":"IC member absent leave personal reason minimum quorum hearing","popular":false,"related":["po-personal-absence","external-member-absence","constitution-versus-quorum"]},{"id":"external-member-absence","topic":"External members and fees","question":"Must an inquiry stop whenever the external member cannot attend?","answer":["The external member is a required part of IC constitution under Section 4(2)(c). Central Rule 7(7) itself specifies three members including the Presiding Officer or Chairperson; it does not separately name the external member in that attendance wording. Check any additional service, institutional or judicial requirements.","This is not permission to exclude the external member from the inquiry or final evaluation. Ensure meaningful independent participation and review the hearing, evidence and decision context. Rescheduling or other lawful corrective steps may be needed. Neither “every absence invalidates everything” nor “quorum alone cures every defect” is a safe universal answer."],"basis":"Section 4(2)(c); Section 11; applicable Central Rule 7(4), (7)","source":"rules","keywords":"external member absent mandatory every hearing participation quorum leave","popular":false,"related":["external-member-eligibility","ordinary-member-absence","member-conflict-interest"]},{"id":"member-conflict-interest","topic":"Inquiry and evidence","question":"What is a conflict of interest for an IC member, and how should it be handled?","answer":["Relevant concerns can include being a material witness, a close personal or financial relationship with a party, prior involvement in the disputed events or an advisory relationship that compromises independence. Disclose the circumstances promptly and record how they are assessed. Employer nomination or an allegation of bias alone does not decide every case.","A direct personal interest must not be ignored. Consider recusal and lawful replacement/reconstitution, appropriate access restrictions and a fair opportunity to raise concerns. Preserve a reasoned record; do not let informal substitutions or a conflicted person’s own assertion of neutrality settle the issue. The correct response depends on the actual facts and governing law."],"basis":"Sections 4 and 11; natural justice; Rashi v. Union of India, 4 December 2020 (reproduced judgment)","source":"rashi","keywords":"conflict interest bias recusal impartial independence relatives lawyer witness panel counsel","popular":false,"related":["committee-change-continuity","external-member-eligibility"]},{"id":"committee-change-continuity","topic":"IC and LC constitution","question":"Must an inquiry restart if a member resigns, is replaced or reaches the end of a term?","answer":["There is no single automatic restart or automatic-continuation answer. Verify the effective nomination orders, valid constitution and attendance, the reason for the change, the governing service/institutional framework and any court directions. Keep the earlier record intact.","Document a lawful handover, access authority and how the reconstituted Committee will fairly consider material already recorded. Further hearing, recall or renewed opportunity may be required. Do not backdate membership, silently rewrite past proceedings or assume that the original 90-day clock restarts because membership changed."],"basis":"Sections 4, 11 and 16; applicable Central Rule 7(4), (7)","source":"act","keywords":"replacement reconstitution resign resignation expired term continuity restart enquiry inquiry change handover","popular":false,"related":["ic-reappointment-three-years","po-personal-absence","member-conflict-interest"]},{"id":"missing-unqualified-external-member","topic":"External members and fees","question":"What if there is no external member, or the appointed external member is not qualified?","answer":["A qualifying external member is a required part of IC constitution under Section 4(2)(c). An HR representative, employee or unqualified nominee cannot simply be labelled external. Check the current written order, eligibility, independence and any conflict before proceeding.","Seek prompt lawful correction/reconstitution through the employer and competent advice on the pending matter. A later appointment does not automatically cure every earlier defect. Do not assume the LC automatically takes over an ordinary employee complaint solely because a 10-plus-worker employer has a defective IC; forum and procedural remedies require review."],"basis":"Sections 4(1)–(2), 6 and 11","source":"act","keywords":"no external member missing unqualified invalid defective qualification","popular":false,"related":["external-member-eligibility","missing-or-unknown-ic","member-conflict-interest"]},{"id":"shebox-nodal-officer-gender","topic":"SHe-Box and nodal officers","question":"Must the SHe-Box Nodal Officer be female, or can a man be appointed?","answer":["Do not transfer the woman Presiding Officer requirement under Section 4(2)(a) to a separate portal-coordination role. A man is not excluded merely by that PO provision. Official government records include male SHe-Box nodal appointments, but this does not by itself certify every private-portal role or account arrangement.","Confirm the exact organisational/State/District portal role, written designation and current authority directions. Current private-dashboard restrictions have not been independently verified here. The coordinator does not become the IC/LC or decide the complaint. The statutory local-area officer under Section 6(2) is another distinct role."],"basis":"SHe-Box role distinction; Section 4(2)(a); official nodal appointment record","source":"nodalRecord","keywords":"male female gender man woman she box nodal officer","popular":false,"related":["shebox-nodal-officer-who","portal-versus-statutory-nodal","statutory-nodal-responsibilities"]},{"id":"statutory-nodal-responsibilities","topic":"SHe-Box and nodal officers","question":"What are the roles and responsibilities of the Nodal Officer under Section 6(2)?","answer":["The District Officer designates a nodal officer for each specified block, taluka or tehsil in rural/tribal areas and ward or municipality in urban areas. The statutory task is to receive complaints and forward them to the concerned LC within seven days of receipt. This is days, not the separate seven-working-day respondent-service rule.","Maintain secure receipt/forwarding records and protect confidentiality. The officer is an access/forwarding point, not an independent adjudicator who can suppress a complaint, decide merits or replace the LC. Additional duties must come from a valid designation or applicable direction. A company’s SHe-Box coordinator is not automatically this statutory officer."],"basis":"Sections 5, 6(2), 11 and 16","source":"act","keywords":"6(2) nodal officer roles responsibilities block taluka tehsil ward municipality seven forwarding","popular":false,"related":["portal-versus-statutory-nodal","shebox-nodal-role"]},{"id":"burden-standard-proof","topic":"Inquiry and evidence","question":"Who bears the burden of proof in a POSH inquiry, and what is the standard of proof?","answer":["Distinguish the obligation to substantiate an allegation from the standard used to evaluate evidence. A complaint is not proof of guilt, and the respondent is not automatically required to prove innocence merely because a complaint is made. The Committee must fairly examine the material and competing explanations under the applicable framework.","In disciplinary inquiries, the Supreme Court discusses preponderance of probabilities rather than the criminal-trial test of proof beyond reasonable doubt (Dilip Paul, paragraphs 92–93). This does not mean guesswork or automatic acceptance/rejection of either party’s account. Assess reliable evidence, context and fair opportunity; non-proof alone does not establish a malicious complaint under Section 14."],"basis":"Sections 11 and 14; applicable service rules; Union of India v. Dilip Paul, 6 November 2023, paras 92–93","source":"dilipPaul","keywords":"burden proof evidence balance probabilities preponderance innocence prove allegations","popular":false,"related":["appreciation-evidence","no-eyewitness","unproved-not-malicious"]},{"id":"annual-awareness-planning","topic":"IC and LC constitution","question":"How many POSH awareness sessions should we plan each year—one or two?","answer":["The Act requires employee awareness programmes at regular intervals and IC orientation; the central provisions do not prescribe a universal one-or-two-session annual minimum. Any applicable sector, State or institutional directions still need checking.","As a planning recommendation, schedule one or two well-spaced employee awareness sessions each year, induction for new joiners and targeted refreshers after significant changes or identified gaps. Plan separate IC orientation/capacity building, including for new members. Increase frequency where workforce size, shifts, turnover or risk warrant it. This is a recommended baseline, not a statutory minimum, maximum or compliance certificate."],"basis":"Section 19(c); Central Rule 13; recommended annual planning","source":"rules","keywords":"1 2 one two sessions per year annual training awareness frequency recommended not mandatory minimum","popular":false,"related":["awareness-training-mandatory","missing-awareness-consequences","committee-meeting-frequency"]},{"id":"committee-meeting-frequency","topic":"IC and LC constitution","question":"How often should an IC or LC meet—monthly, quarterly or only when a complaint arises?","answer":["Separate preparedness/governance meetings from hearings in a live inquiry. The central POSH Act and Rules do not set one universal routine meeting count for every IC and LC. Check applicable government, State, service and institutional directions.","DoPT’s central-government guidance describes meeting once a quarter, even without a live case, as desirable for preparedness. Do not turn that wording into a universal binding quarterly rule for all private ICs or LCs. Use periodic reviews as an operational plan; live hearings must be convened as needed with lawful notice, participation and fair opportunity within the applicable deadlines—not postponed until the next quarterly review."],"basis":"DoPT compilation, 4 November 2022, employer duties/OM 2 February 2015; Sections 11 and 19","source":"dopt","keywords":"IC LC meetings frequency monthly quarterly quarter no complaint governance hearing","popular":false,"related":["annual-awareness-planning","hearing-quorum"]},{"id":"support-staff-presiding-officer","topic":"IC and LC constitution","question":"Our only woman employee is D-grade/support staff. Can we appoint her as Presiding Officer?","answer":["Being the only woman, or the longest-serving woman, does not by itself satisfy Section 4(2)(a)’s senior-level employment requirement. Assess actual senior-level eligibility in the relevant organisation; do not simply relabel a support-staff role for convenience.","If no eligible senior woman is available, follow the statutory sequence through other offices/administrative units and then the further permitted workplace/department/organisation alternatives. Document the basis. Do not leave a required IC unconstituted or substitute a male PO. Applicable UGC rules for HEIs contain additional faculty-rank requirements; the ordinary workplace answer cannot replace those."],"basis":"Section 4(2)(a) and its provisos; applicable UGC Regulation 4","source":"act","keywords":"D grade D-grade support staff only female only woman junior senior presiding officer peon housekeeping","popular":false,"related":["no-presiding-officer","ugc-committee-composition"]},{"id":"external-member-contacts","topic":"External members and fees","question":"Can you suggest contacts to enquire about an external-member appointment?","answer":["The owner has supplied the two contacts below for an initial external-member enquiry. Their stated experience is 5+ years working with the POSH Act. This is owner-provided profile information, not independent verification, government empanelment or a guarantee of eligibility or availability.","Before appointment, verify the relevant background under Section 4(2)(c), independence, conflicts, availability, scope and agreed fees. Start with a general enquiry; do not send identifying complaint files before authority and confidentiality arrangements are established. This directory entry does not appoint anyone or create a professional engagement."],"basis":"Owner-provided contact directory; Section 4(2)(c) eligibility remains separate","source":"ownerContacts","keywords":"Ankur Agrawal Pooja 7902171932 9355096967 external member contacts suggest experience","popular":false,"related":["external-member-eligibility","member-conflict-interest","ic-external-member-fees"],"contacts":[{"name":"Ankur Agrawal","phone":"+91 79021 71932","tel":"+917902171932","email":"ankur.attorneyatlaw@gmail.com","experience":"5+ years in POSH — as stated by the owner"},{"name":"Ms. Pooja","phone":"+91 93550 96967","tel":"+919355096967","email":"panchalpooja2019@gmail.com","experience":"5+ years in POSH — as stated by the owner"}]},{"id":"compliance-missed-points","topic":"Employer compliance and consequences","question":"What other commonly missed POSH compliance points should we check?","answer":["Common gaps include expired nomination orders, confusion between constitution and hearing quorum, ineffective complaint contact channels, unmanaged conflicts, unrecorded service/receipt dates and treating all deadlines as working days. Also check accessible assistance, regular awareness and member orientation, confidentiality and safeguards against retaliation.","Keep the annual-report obligation distinct from an individual inquiry report; distinguish a SHe-Box coordinator from the Section 6(2) officer; and verify the competent appeal forum and applicable service/sector rules. A checklist or session certificate alone cannot establish full compliance. Use the linked questions for each issue rather than treating this as an automatic compliance score."],"basis":"Sections 4, 6, 9, 11, 13, 16, 18–22; applicable rules","source":"act","keywords":"missing gaps checklist readiness audit common mistakes compliance","popular":false,"related":["committee-tenure-vacancies","calendar-working-days","annual-versus-inquiry-report","appeal-ic-to-lc"]},{"id":"ugc-committee-composition","topic":"UGC / Colleges","question":"Does a college ICC always need nine members under the UGC regulations?","answer":["Regulation 4 specifies a woman faculty Presiding Officer, two faculty members, two non-teaching employees and one qualifying external member: six base positions. Three elected student representatives are added if the matter involves students, making nine in that situation. It is not a universal always-nine rule.","At least half the total membership must be women. The PO rank requirement is at least Professor for a university and Associate Professor/Reader for a college, with the prescribed fallback. Senior administrators listed in Regulation 4(3), such as VC, Registrar, Deans and HoDs, are excluded from ICC membership. Check the applicable HEI framework."],"basis":"UGC Regulations 2015, Regulation 4(1)–(3)","source":"ugc","keywords":"UGC college university nine 9 six 6 members faculty non teaching professor presiding officer","popular":false,"related":["ugc-student-elections","support-staff-presiding-officer"]},{"id":"ugc-student-elections","topic":"UGC / Colleges","question":"Must UGC student representatives be elected, or can the college management nominate them?","answer":["For the student positions in Regulation 4(1)(c), the regulations specify three students at undergraduate, master’s and research-scholar levels respectively, elected through a transparent democratic procedure when the matter involves students. Do not treat management handpicking as equivalent to that requirement.","Check the applicable institutional election process and the actual student categories. This differs from the Executive Authority’s nomination of the faculty, non-teaching and external positions. Keep the selection process, gender composition and eligibility records current."],"basis":"UGC Regulation 4(1)(b)–(d), 4(2)","source":"ugc","keywords":"UGC students student representatives election elected nomination democratic transparent undergraduate masters research","popular":false,"related":["ugc-committee-composition"]},{"id":"ugc-policy-review-training","topic":"UGC / Colleges","question":"Do UGC institutions have additional policy-review and training requirements?","answer":["The UGC framework requires regular orientation/training for ICC members and regular workshops for the HEI community. Regulation 3.2(5) additionally requires a regular half-yearly review of the efficacy and implementation of the anti-sexual-harassment policy.","A half-yearly policy review is not the same thing as a universal law requiring exactly two employee awareness sessions. Plan the applicable HEI reviews, training and workshops separately; keep accurate records and check current institutional/sector directions."],"basis":"UGC Regulations 3.1(j), 3.2(5)–(7)","source":"ugcReview","keywords":"UGC college university half yearly policy review training awareness workshops","popular":false,"related":["annual-awareness-planning","committee-meeting-frequency","ugc-committee-composition"]},{"id":"lc-five-member-composition","topic":"IC and LC constitution","question":"Can a Local Committee have more than five members under the POSH Act?","answer":["Section 7(1) prescribes five LC members: one woman Chairperson under clause (a), one woman working in the specified local area under clause (b), two NGO/association or sexual-harassment-familiar members under clause (c), and the concerned district social-welfare or women-and-child-development officer as an ex-officio member under clause (d).","Unlike the IC provision requiring not less than two employee members, Section 7 does not provide a general open-ended power to add ordinary LC members. An additional invitee, support person or nodal officer should not simply be treated as an extra statutory member or allowed to decide the inquiry. Any notification constituting a larger LC needs examination against its specific lawful authority.","The two clause (c) nominees must satisfy its gender and community representation provisos; at least one should preferably have a legal background or legal knowledge. Composition and hearing quorum are different questions."],"basis":"Act Section 7(1)(a)–(d), including provisos; compare Section 4(2)(b); applicable Central Rules 4 and 7(7)","source":"act","popular":false,"keywords":"LC LCC local committee five 5 six 6 more than maximum composition members"},{"id":"posh-trainer-qualifications","topic":"Employer compliance and consequences","question":"What qualifications are required to be a POSH trainer?","answer":["The central POSH Act and Rules require awareness programmes and IC orientation, but do not prescribe one universal trainer licence, compulsory degree, government certificate or fixed number of years of experience for every trainer. A tender, employer, sector regulator or empanelment programme may impose additional selection requirements.","As a recommended selection standard, check accurate knowledge of the Act and applicable rules, practical inquiry and natural-justice understanding, gender-sensitive facilitation, relevant training experience, audience-language ability, references and up-to-date materials. Law, social work, psychology or related expertise may support competence; a short course certificate alone does not establish it.","Training, legal practice, IC external membership and SHe-Box empanelment are separate roles. Do not present a private trainer certificate as government approval, or assume that being an advocate automatically establishes all training or committee-role qualifications."],"basis":"Act Section 19(c); Central Rule 13(b)–(f); programme-specific selection requirements are separate","source":"rules","popular":false,"keywords":"qualifications qualification POSH trainer educator degree certificate licence license training trainers eligibility"},{"id":"shebox-trainer-empanelment-application","topic":"SHe-Box and nodal officers","question":"How can an individual or organisation seek SHe-Box trainer empanelment?","answer":["Use only the official SHe-Box portal and the current MWCD or competent State instructions for the relevant empanelment category. Trainer empanelment is different from registering a workplace or uploading an IC constitution order. Submission of an application is not approval.","Prepare a documented profile of relevant qualifications, POSH or women’s-rights work, training experience, sample modules, references and supporting credentials. Organisations should also check current registration and organisational-document requirements. This is a preparation checklist, not a verified statement that each document is mandatory under the live portal.","The official portal returned access-denied responses during this review. Current minimum qualifications, approval authority, application fields, fees if any, validity and renewal conditions could therefore not be independently confirmed. Obtain the current published instructions or written confirmation through the official portal support / relevant WCD authority before applying. Do not treat an old empanelment PDF, a provider’s badge or a pending application as proof of current approval.","Empanelment does not by itself appoint a person to an IC or LC, establish eligibility under Section 4(2)(c) or Section 7(1)(c), or confer authority to conduct another organisation’s inquiry."],"basis":"Official SHe-Box / MWCD administrative programme; Act Sections 4(2)(c), 7(1)(c) and 19(c) distinguish committee eligibility and training duties","source":"shebox","popular":false,"keywords":"SHeBox She Box empanelment empanelled trainer individuals organisations qualification eligibility application approval registration"}];
const topics=[...new Set(items.map(x=>x.topic))];
const normalize=x=>String(x||'').normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();
function filter(query='',topic='All topics'){const aliases={icc:'internal committee',lcc:'local committee',posh:'sexual harassment',nda:'nda',exparte:'ex parte',shebox:'she box'};const words=normalize(query).split(/\s+/).filter(Boolean).flatMap(w=>(aliases[w]||w).split(' '));return items.filter(x=>(topic==='All topics'||x.topic===topic)&&words.every(w=>normalize([x.question,...x.answer,x.basis,x.keywords].join(' ')).includes(w)));}
const glossary=[['BNS','Bharatiya Nyaya Sanhita, 2023: criminal offences; transition and date rules matter.'],['BNSS','Bharatiya Nagarik Suraksha Sanhita, 2023: criminal procedure; distinct from the POSH inquiry.'],['SHe-Box','The government’s Sexual Harassment electronic Box portal; separate from this Navigator.'],['Nodal Officer','A coordination role; statutory local-area and organisation portal roles must be distinguished.'],['IC / ICC','Internal Committee; ICC is the older name commonly used.'],['LC / LCC','Local Committee; LCC is the older name commonly used.'],['PO','Presiding Officer of the IC.'],['DO','District Officer under the Act.'],['NDA','A confidentiality undertaking, distinct from the statutory duty.'],['Natural justice','Fair procedure, including a meaningful opportunity to be heard.'],['Ex parte','Proceeding without a party, subject to applicable safeguards.'],['Appreciation of evidence','Assessing the relevance, reliability and weight of material.']];
if(typeof module==='object'&&module.exports){module.exports={items,topics,filter,glossary};return;}
const escape=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sources={dopt:{label:'Official DoPT compilation — government-service context',url:'https://www.dgt.gov.in/sites/default/files/2024-10/DoPT%20OM%20dated%2004-11-2022%20%281%29_0.pdf'},nodalRecord:{label:'Government SHe-Box nodal appointment record',url:'https://api.sci.gov.in/supremecourt/2023/22553/22553_2023_6_11_61891_Order_21-May-2025.pdf'},dilipPaul:{label:'Dilip Paul — reproduced Supreme Court judgment',url:'https://sooperkanoon.com/case/1230607/union-india-vs-dilip-paul'},ownerContacts:{label:'Owner-provided contacts; verify before appointment',url:'#faq/external-member-contacts'},ugc:{label:'UGC Regulations — official compendium, Regulation 4',url:'https://www.ugc.gov.in/e-book/UGC_Regulation/files/basic-html/page986.html'},ugcReview:{label:'UGC Regulations — official compendium, policy reviews',url:'https://www.ugc.gov.in/e-book/UGC_Regulation/files/basic-html/page985.html'},rashi:{label:'Rashi — reproduced Delhi High Court judgment',url:'https://indiankanoon.org/doc/157949099/'},bns:{label:'NCRB — official BNS reference',url:'https://www.ncrb.mha.gov.in/uploads/SankalanPortal/ChaptersBNS.html'},shebox:{label:'Official SHe-Box portal — live directory requires confirmation',url:'https://shebox.wcd.gov.in/'},sheboxManual:{label:'Official private-head-office manual — current screens require confirmation',url:'https://shebox.wcd.gov.in/assets/usermanual/Private-Head-Office-User-Manual.pdf'},sheboxCompliance:{label:'MWCD parliamentary reply — 1 April 2026',url:'https://sansad.in/getFile/annex/270/AU4313_wIJQyF.pdf?source=pqars'},act:{label:'POSH Act — India Code',url:'https://www.indiacode.nic.in/bitstream/123456789/2104/1/A2013-14.pdf'},rules:{label:'Central Rules — official Gazette',url:'https://spniwcd.wcd.gov.in/uploads/pdf/1719914401_2NUqe91gql.pdf'},judgment:{label:'Supreme Court primary judgment',url:'https://api.sci.gov.in/supremecourt/2023/26792/26792_2023_3_1501_66764_Judgement_10-Dec-2025.pdf'},community:{label:'View community',url:'#community'},plans:{label:'View plans and limits',url:'#pricing'},guidance:{label:'Explore free guidance',url:'#journeys'}};
function render(app,path){
 if(path==='faq'||path==='faq/find'){root.NavigatorFinder.render(app);return;}
 if(/^faq\/(library|ref-|case-)/.test(path)){root.NavigatorLibrary.render(app,path);return;}
 let topic='All topics';const opened=new Set();const deepId=path.split('/')[1]==='practical'?null:path.split('/')[1];if(deepId)opened.add(deepId);
 app.innerHTML=`<section class="app-heading"><div class="wrap"><div><a class="app-back" href="#home">← Back to homepage</a><small>FREQUENTLY ASKED QUESTIONS</small><h1 id="faq-page-title">Clear answers to common POSH questions.</h1><p>Understand the distinctions people often miss: forum, timelines, confidentiality, findings, community privacy and what the platform actually offers.</p></div><span class="app-mini">${items.length} answers · ${topics.length} topics</span></div></section><div class="app-bg"><div class="wrap workspace faq-shell"><aside class="faq-notice"><strong>General guidance, not a decision on your case.</strong><p>Applicable service, institutional, sector and jurisdictional rules must be checked. Central Rule 7 references are qualified where applicable. This page does not file a complaint, determine guilt or replace advice on a particular matter.</p><p>Search general terms only. Do not enter names or confidential case details. Search and topic filtering stay in your browser.</p></aside><p class="faq-edition">Content edition: 31 October 2026 · General Indian POSH framework. Independent legal sign-off remains pending.</p><aside class="faq-library-entry"><h2>Search the complete question directory</h2><p>400 numbered questions across 25 categories, with topic, provision and case-reference indexes. Each entry identifies its editorial status.</p><a class="btn btn-dark" href="#faq">Search all FAQs</a></aside><details class="faq-glossary"><summary>Understand the terms: IC, LC, PO, DO and more</summary><dl>${glossary.map(([term,meaning])=>`<div><dt>${escape(term)}</dt><dd>${escape(meaning)}</dd></div>`).join('')}</dl></details><details class="faq-popular"><summary>Browse 12 commonly misunderstood questions</summary><div>${items.filter(x=>x.popular).map(x=>`<a href="#faq/${escape(x.id)}">${escape(x.question)}</a>`).join('')}</div></details><section class="faq-controls" aria-label="Find a question"><label for="faq-search">Search questions and answers</label><input id="faq-search" type="search" placeholder="Try: SHe-Box, external member, six copies or NDA" autocomplete="off" maxlength="160"><div class="faq-topics" role="group" aria-label="Filter FAQ topics">${['All topics',...topics].map(t=>`<button type="button" data-faq-topic="${escape(t)}" aria-pressed="${t==='All topics'}">${escape(t)}</button>`).join('')}</div><div class="faq-actions"><button type="button" class="btn btn-light" id="faq-expand">Expand matching answers</button><button type="button" class="btn btn-light" id="faq-collapse">Collapse answers</button><button type="button" class="btn btn-light" id="faq-reset">Clear filters</button></div></section><p id="faq-result-count" role="status" aria-live="polite"></p><div id="faq-results"></div><div id="faq-empty" class="faq-empty" hidden><h2>No matching question found.</h2><p>Try fewer words or another topic. For a general discussion, you can ask the moderated community without including personal details.</p><a href="#community" class="btn btn-light">Visit community</a></div><aside class="faq-source-help"><strong>Source link unavailable?</strong><p>Government PDF links may change or fail to load. Find the POSH Act and Rules through the <a href="https://www.wcd.gov.in/documents/legislations" target="_blank" rel="noopener noreferrer">Ministry’s legislation directory</a>. Check the exact provision and applicable service rules, rather than relying only on a short answer.</p><a href="mailto:trainings@thecosmicenergizers.com?subject=Navigator%20FAQ%20correction">Suggest a general correction</a><p>Do not email case files or identifying details. No response time is promised.</p></aside><section class="faq-suggest"><h2>What should we explain next?</h2><p>Suggest a general question for a future FAQ. Every submission is moderated, and an editor checks sources before adding an answer. No sign-in or contact details are needed.</p><a class="btn btn-dark" href="#community/suggest-faq">Suggest a future FAQ</a><p>Leave out names, employer details and confidential case information. This does not file a complaint.</p></section><section class="faq-next"><h2>Choose your next step</h2><a href="#journeys" class="btn btn-dark">Free individual guidance</a> <a href="#demo" class="btn btn-light">Nine inquiry stages</a> <a href="#community" class="btn btn-light">General community questions</a><p>Public FAQ explanations do not unlock detailed paid inquiry tools. Professional workspace, NDA document handling and paid-service activation remain planned.</p></section></div></div>`;
 const results=app.querySelector('#faq-results'),search=app.querySelector('#faq-search');
 function apply(){const matches=filter(search.value,topic);app.querySelector('#faq-result-count').textContent=matches.length+' of '+items.length+' questions shown'+(topic==='All topics'?'':' · '+topic);app.querySelector('#faq-empty').hidden=matches.length>0;
 results.innerHTML=matches.map(x=>{const source=sources[x.source];const related=x.related?x.related.map(id=>items.find(y=>y.id===id)).filter(Boolean):items.filter(y=>y.topic===x.topic&&y.id!==x.id).slice(0,2);return `<details class="faq-detail" id="faq-${escape(x.id)}" data-faq-id="${escape(x.id)}" ${opened.has(x.id)?'open':''}><summary><span class="faq-topic-label">FAQ ${root.NavigatorFinder?.numberFor(x.id)||'—'} · ${escape(x.topic)}</span><span>${escape(x.question)}</span></summary><div class="faq-answer">${x.answer.map(p=>`<p>${escape(p)}</p>`).join('')}${x.contacts?`<div class="faq-contacts">${x.contacts.map(c=>`<article><strong>${escape(c.name)}</strong><p>${escape(c.experience)}</p><a href="tel:${escape(c.tel)}">${escape(c.phone)}</a><a href="mailto:${escape(c.email)}">${escape(c.email)}</a></article>`).join('')}</div>`:''}<p class="faq-basis"><strong>Basis:</strong> ${escape(x.basis)} · <a href="${escape(source.url)}" ${source.url.startsWith('https:')?'target="_blank" rel="noopener noreferrer"':''}>${escape(source.label)}</a></p>${root.NavigatorLegal?.citationHTML(x)||''}<nav class="faq-related" aria-label="Related questions"><strong>Related questions</strong>${related.map(y=>`<a href="#faq/${escape(y.id)}">${escape(y.question)}</a>`).join('')}</nav><a class="faq-permalink" href="#faq/${escape(x.id)}">Link to this answer</a></div></details>`}).join('');
 for(const button of app.querySelectorAll('[data-faq-topic]'))button.setAttribute('aria-pressed',String(button.dataset.faqTopic===topic));}
 results.addEventListener('toggle',e=>{if(!e.target.matches('[data-faq-id]'))return;if(e.target.open)opened.add(e.target.dataset.faqId);else opened.delete(e.target.dataset.faqId)},true);
 search.addEventListener('input',apply);
 for(const button of app.querySelectorAll('[data-faq-topic]'))button.addEventListener('click',()=>{topic=button.dataset.faqTopic;apply()});
 app.querySelector('#faq-expand').addEventListener('click',()=>{for(const d of results.querySelectorAll('details')){opened.add(d.dataset.faqId);d.open=true}});
 app.querySelector('#faq-collapse').addEventListener('click',()=>{for(const d of results.querySelectorAll('details')){opened.delete(d.dataset.faqId);d.open=false}});
 app.querySelector('#faq-reset').addEventListener('click',()=>{topic='All topics';search.value='';apply();search.focus()});
 apply();document.title='Detailed FAQs | POSH Inquiry Navigator';
 if(deepId){const item=app.querySelector('#faq-'+CSS.escape(deepId));if(item)requestAnimationFrame(()=>{item.scrollIntoView({block:'start'});item.querySelector('summary').focus({preventScroll:true})});else{app.querySelector('#faq-result-count').textContent='That answer link was not found. Browse or search all questions below.';}}
}
root.NavigatorFAQ={render,count:items.length,topicCount:topics.length,getIndex:()=>items.map(x=>({...x}))};
})(typeof window==='undefined'?globalThis:window);
